// Category A — React Aria owns slider behavior and injects the channel gradient.
import {
  ColorSlider as AriaColorSlider,
  Label,
  SliderTrack,
  ColorThumb,
} from "react-aria-components";
import type { ColorSliderProps as AriaColorSliderProps } from "react-aria-components";
import { useId, type Ref } from "react";
import "./ColorSlider.css";

export interface ColorSliderProps
  extends Omit<AriaColorSliderProps, "className" | "children"> {
  /**
   * Visible label.
   *
   * React Aria names this control from the channel when none is given, but that name is carried by
   * an `aria-label` on the track, which is not a VISIBLE label: axe's `label-title-only` fires the
   * moment such a control also has an `aria-describedby`, which `description` below adds. The rule is right about the shape rather
   * than the attribute — helper text under an unlabelled control describes something the reader
   * cannot name. `ColorArea` and `ColorWheel` take no `label` because React Aria provides them no
   * `LabelContext` at all; they carry the channel name and nothing else.
   */
  label?: string;
  /**
   * Helper text describing the control, wired to its `aria-describedby`.
   *
   * React Aria provides no description slot for any of the three `Color*` controls (in the
   * installed package `ColorSlider.mjs`, `ColorArea.mjs` and `ColorWheel.mjs`
   * mention `description` zero times, where `TagGroup` and `ListBox` hand `descriptionProps` to a
   * `TextContext`), so a `Text` slotted here would render and describe nothing. The id is
   * generated and passed explicitly, the same way `Slider` does it.
   *
   * It goes on the ROOT, not the thumb: `ColorThumb` reads its props from context and does not
   * render the input, so the element carrying the control role is built by the root from React
   * Aria's own hook. (`Slider` is the opposite — there `SliderThumb` renders it, so the id goes on
   * the thumb.) Merged with any
   * `aria-describedby` the consumer passes, rather than replacing it.
   */
  description?: string;
  /** Additional class. sd-color-slider is always preserved. */
  className?: string;
  /** Passed to the underlying slider DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorSlider({ label, description, className, ref, ...props }: ColorSliderProps) {
  const descriptionId = useId();
  return (
    <AriaColorSlider
      {...props}
      aria-describedby={
        [props["aria-describedby"], description ? descriptionId : null].filter(Boolean).join(" ") ||
        undefined
      }
      ref={ref}
      className={className ? `sd-color-slider ${className}` : "sd-color-slider"}
    >
      {label && <Label className="sd-color-slider__label sd-type-label-medium">{label}</Label>}
      <SliderTrack className="sd-color-slider__track">
        <ColorThumb className="sd-color-slider__thumb" />
      </SliderTrack>
      {description && (
        <div id={descriptionId} className="sd-color-slider__description sd-type-caption-medium">
          {description}
        </div>
      )}
    </AriaColorSlider>
  );
}

.sd-color-slider {
  display: inline-flex;
  /* Column, because the root holds a label and a description as well as the track: as a row they
     were laid out BESIDE the track and the helper text wrapped into a five-word column. With only a
     track child, which is every call that passes neither, a column renders identically. */
  flex-direction: column;
  gap: var(--sd-color-slider-gap);

  /* Cross-axis centring for the thumb, the same local-intermediate pattern Slider uses and the
     same comment applies: React Aria sets the POSITION axis inline (left horizontally, top
     vertically), so these centre only the other one. Without them the thumb sits eight pixels above
     its own track. */
  --sd-color-slider-thumb-top-current: 50%;
  --sd-color-slider-thumb-left-current: auto;

  /* The thumb's TRAVEL, pulled in by half a thumb at each end. Without it the thumb is centred on
     its value and half of it hangs off the track at either extreme: measured 8px on a 16px thumb
     at both 0 and 360. React Aria writes `left`/`top` and the translate INLINE, so the only lever
     is the containing block, and an abspos child resolves percentages against the PADDING box —
     which padding cannot shrink but a transparent BORDER can, while the gradient still paints the
     whole border box. Based on the RESTING size: a focused thumb grows and may reach a little past
     the end, which is the conventional trade and keeps the resting thumb flush with the track. */
  --sd-color-slider-track-inset-inline-current: calc(var(--sd-color-slider-thumb-size) / 2);
  --sd-color-slider-track-inset-block-current: 0px;
}
.sd-color-slider[data-orientation="vertical"] {
  --sd-color-slider-thumb-top-current: auto;
  --sd-color-slider-thumb-left-current: 50%;
  /* and the travel inset swaps onto the other axis with it */
  --sd-color-slider-track-inset-inline-current: 0px;
  --sd-color-slider-track-inset-block-current: calc(var(--sd-color-slider-thumb-size) / 2);
}

.sd-color-slider__track {
  width: var(--sd-color-slider-track-width-horizontal);
  height: var(--sd-color-slider-track-height-horizontal);
  border-radius: var(--sd-color-slider-track-radius);
  corner-shape: round;
  flex-shrink: 0;
  forced-color-adjust: none;
  /* Not chrome: the thumb's travel inset, transparent on purpose. */
  border-inline: var(--sd-color-slider-track-inset-inline-current) solid transparent;
  border-block: var(--sd-color-slider-track-inset-block-current) solid transparent;
}
.sd-color-slider__track[data-orientation="vertical"] {
  width: var(--sd-color-slider-track-width-vertical);
  height: var(--sd-color-slider-track-height-vertical);
}

.sd-color-slider[data-disabled] {
  opacity: var(--sd-state-disabled);
}

.sd-color-slider__thumb {
  top: var(--sd-color-slider-thumb-top-current);
  left: var(--sd-color-slider-thumb-left-current);
  width: var(--sd-color-slider-thumb-size);
  height: var(--sd-color-slider-thumb-size);
  border: var(--sd-color-slider-thumb-border-width) solid var(--sd-color-slider-thumb-border);
  border-radius: var(--sd-color-slider-thumb-radius);
  corner-shape: round;
  box-shadow: var(--sd-color-slider-thumb-shadow);
  box-sizing: border-box;
}
/* Hover/drag feedback halo (RAC ColorThumb emits data-hovered/data-dragging), mirrors Slider. */
.sd-color-slider__thumb[data-hovered] {
  box-shadow: var(--sd-color-slider-thumb-shadow-hover);
}
.sd-color-slider__thumb[data-dragging] {
  box-shadow: var(--sd-color-slider-thumb-shadow-dragging);
}
.sd-color-slider__thumb[data-focus-visible] {
  width: var(--sd-color-slider-thumb-size-focused);
  height: var(--sd-color-slider-thumb-size-focused);
}

/* On the text line with every other field's label (component-contract.md §6 rule 8). */
.sd-color-slider__label {
  color: var(--sd-color-slider-label-foreground);
  padding-inline-start: var(--sd-color-slider-text-padding-inline);
}

.sd-color-slider__description {
  color: var(--sd-color-slider-description-foreground);
  padding-inline-start: var(--sd-color-slider-text-padding-inline);
}
